with p as (select id from liq_proveedores where nombre='Citigroup')
update liq_proveedores set email_patron='first.last@citi.com', email_patron_fuente='https://www.businesswire.com/news/home/20220621005892/en (comunicado Citi/METACO 2022: contacto de medios Rekha Jogia-Soni, rekha.jogiasoni@citi.com — nombre.apellido@citi.com, guiones eliminados). Verificación 2026-10-18: la página no pudo reabrirse desde este entorno (bloqueo de red 403 del proxy), por lo que la instancia publicada NO fue confirmada visualmente en esta pasada; el patrón coincide con el formato estándar de contactos de prensa de Citi, pero debe reconfirmarse manualmente antes de usar los correos derivados. · confianza: media',
 canales_publicos='[{"canal": "Página oficial de la unidad Digital Assets (Citi)", "valor": "https://www.citigroup.com/global/businesses/digital-assets", "fuente": "https://www.citigroup.com/global/businesses/digital-assets"}, {"canal": "Estrategia Digital Assets / CIDAP (Citi)", "valor": "https://www.citigroup.com/global/about-us/strategy/digital-assets", "fuente": "https://www.citigroup.com/global/about-us/strategy/digital-assets"}, {"canal": "Sala de prensa y contactos de medios", "valor": "https://www.citigroup.com/global/news/press-release", "fuente": "https://www.citigroup.com/global/news/press-release"}, {"canal": "Insights etiquetados ''Citi Digital Assets''", "valor": "https://www.citigroup.com/global/insights/tags/citi-digital-assets", "fuente": "https://www.citigroup.com/global/insights/tags/citi-digital-assets"}, {"canal": "LinkedIn (página corporativa Citi)", "valor": "https://www.linkedin.com/company/citi", "fuente": "https://www.linkedin.com/company/citi"}, {"canal": "X / Twitter", "valor": "@Citi", "fuente": "https://x.com/Citi"}, {"canal": "Portal de empleos: evidencia de roles regionales de comercialización de tokenización en Services (p. ej. ''Head of Europe for Digital Assets Tokenisation and Commercialisation'')", "valor": "https://jobs.citi.com/job/london/director-services-head-of-europe-for-digital-assets-tokenisation-and-commercialisation/287/92164064176", "fuente": "https://jobs.citi.com/job/london/director-services-head-of-europe-for-digital-assets-tokenisation-and-commercialisation/287/92164064176"}, {"canal": "Portal de empleos: vacante ''Head of Business Development, Citi Services (Partnerships & Innovation Org)'' en Nueva York (junio 2026) — confirma que la organización de Partnerships & Innovation sigue activa y reporta al Head of Partnership & Innovation", "valor": "https://jobs.citi.com/job/new-york/head-of-business-development-citi-services-partnerships-and-innovation-org/287/96257343744", "fuente": "https://jobs.citi.com/job/new-york/head-of-business-development-citi-services-partnerships-and-innovation-org/287/96257343744"}]'::jsonb, ruta_recomendada='1) Primer correo a Biswarup Chatterjee (MD, Global Head of Partnerships & Innovation, Citi Services: dueño de alianzas e inversiones en fintech/infraestructura financiera y del portafolio blockchain; rol reconfirmado en 2026 por American Banker y por vacantes de Citi de junio 2026) con CC a Ryan Rugg (Global Head of Digital Assets, Services, dueña de Citi Token Services; reporta a Chatterjee). Posicionar a Kabal como infraestructura regulada (PSAD-0056) para distribución secundaria en Centroamérica y liquidez/settlement 24/7 vía CTS. Antes de enviar, reconfirmar manualmente el patrón nombre.apellido@citi.com abriendo el comunicado de BusinessWire citado (no pudo reabrirse en esta verificación). 2) Intro cálida: pedir referencia a SIX o Kaleido (socios de CTS ya en el tracker); alternativamente Chainlink/Circle si existe relación comercial con ellos. 3) Ruta LatAm en paralelo: Driss Temsamani (Head of Digital, Américas, Services/TTS) para patrocinio interno y conexión con el equipo de Citi en Costa Rica/El Salvador; OBLIGATORIO validar su cargo vigente en LinkedIn antes de escribir (toda la evidencia pública es de 2023; no se halló nada de 2025-2026). 4) Fallback: contacto de prensa de Citi Services (Rekha Jogia-Soni; correo según patrón, publicado en comunicado de 2022 no reverificado en esta pasada) para que enrute al equipo de digital assets, o Mark Attard (Head of Digital Assets and Client Relationships, Asia South/JANA, Singapur) si el objetivo es cross-listing en Singapur/HK.',
 decisor=coalesce('Ryan Rugg — Global Head of Digital Assets, Citi Services (antes Global Head of Digital Assets, TTS)',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Citi Token Services (CTS) operando en cuatro mercados; prioridad declarada por Jane Fraser; socios Kaleido, SIX, Siam Commercial Bank.'||E'\n'||'Investigación automática 2026-10-18 (lote EXPLORE del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 12 búsquedas. Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='Citigroup'), v.* from (values
('Biswarup Chatterjee','Managing Director, Global Head of Partnerships & Innovation, Citi Services','Citi Services (TTS + Securities Services) – Partnerships & Innovation / Digital Assets','Nueva York, EE. UU.',null,'biswarup.chatterjee@citi.com','patron_no_verificado','entrada',1,'Lidera alianzas e inversiones en fintech e infraestructura financiera y el desarrollo de productos blockchain (depósitos tokenizados, coins, cripto) en Services; Ryan Rugg le reporta (American Banker, 2026). Es el punto de entrada natural para una alianza de distribución/liquidez con un PSAD regulado.','https://us.money2020.com/agenda/speakers/biswarup-chatterjee-s103-110410','Verificación: rol vigente en 2026 confirmado por American Banker (perfil de Ryan Rugg, 2026: ''reports to Biswarup Chatterjee, global head of partnerships and innovation for Citi Services'') y por la vacante de Citi de junio 2026 ''Head of Business Development, Citi Services (Partnerships & Innovation Org)'' en Nueva York, que reporta al Head of Partnership & Innovation. Fuente original (https://fintechmeetup.com/speaker-list/biswarup-chatterjee) no pudo abrirse desde este entorno (bloqueo de red), así que se sustituyó por el perfil Money20/20 confirmado en búsqueda; perfil adicional en Aspen Ideas (https://www.aspenideas.org/speakers/biswarup-chatterjee, ''Global Head of Partnerships and Innovation, Citigroup Services''). Correo derivado del patrón nombre.apellido@citi.com (no verificado). Ubicación inferida de su rol global y de la vacante NY de su organización; confirmar en LinkedIn.'),
('Ryan Rugg','Global Head of Digital Assets, Citi Services (antes Global Head of Digital Assets, TTS)','Citi Services – Digital Assets / Citi Token Services','Nueva York, EE. UU.',null,'ryan.rugg@citi.com','patron_no_verificado','dueno_programa',2,'Dirige el programa Citi Token Services (depósitos tokenizados, liquidez 24/7, trade) y es la decisora operativa sobre nuevos corredores y socios del producto; reconocida en 2026 por American Banker (Women to Watch #8), con un equipo de 11 personas.','https://www.americanbanker.com/news/2026-the-most-powerful-women-in-banking-women-to-watch-8-ryan-rugg-citi','Verificación: cargo vigente en 2026 confirmado por American Banker (título actual ''global head of digital assets, services'' tras el cambio de nombre de TTS a Services; gestiona 11 empleados; reporta a Biswarup Chatterjee). Fuente confirmada en búsqueda. Correo derivado del patrón nombre.apellido@citi.com (no verificado). Perfil adicional: https://sumsub.com/blog/experts/ryan-rugg/ y https://the-most-powerful-women-in-banking.americanbanker.com/profile/ryan-rugg/'),
('Driss Temsamani','Head of Digital, Américas, Citi Services / Treasury & Trade Solutions (cargo según evidencia de 2023; vigencia 2025-2026 NO confirmada)','Citi Services – Digital (Américas / LatAm)','Américas / LatAm (sede no confirmada)',null,'driss.temsamani@citi.com','patron_no_verificado','cobertura_latam',3,'Responsable digital de TTS para las Américas (EE. UU., Canadá y LatAm) con remit explícito en activos digitales; ha promovido tokenización y Citi Token Services en Centroamérica (Costa Rica) y dio el keynote ''Dinero y tokens'' en LatAm (2023). Puente natural hacia Citi Centroamérica, si sigue en el cargo.','https://us.america-digital.com/speakers/driss-temsamani-head-of-digital-for-the-americas-citi/','Verificación: búsquedas dirigidas a 2025-2026 no arrojaron ninguna fuente que confirme ni refute su cargo actual; toda la evidencia pública es de 2023 (America Digital World Congress, La República CR, entrevista BrainStation, Citi 2023 Fall CAB Welcome Book https://www.citibank.com/tts/sa/flippingbook/2023/2023-Fall-CAB-Welcome-Book/56). Wikipedia (sin fecha) lo describe como MD que lidera banca digital para las Américas. Se mantiene en prioridad 3 pero con ADVERTENCIA reforzada: no escribir sin validar el cargo en LinkedIn. Fuente original (https://www.larepublica.net/noticia/citi-transforma-el-paisaje-bancario-de-costa-rica-con-cuenta-digital-y-tokenizacion-driss-temsamani-director-digital-para-america) no pudo abrirse desde este entorno; se sustituyó por la página de ponente confirmada en búsqueda. Correo derivado del patrón nombre.apellido@citi.com (no verificado).'),
('Mark Attard','Head of Digital Assets and Client Relationships, Citi Services (clústeres Asia South y JANA)','Citi Services – Digital Assets / Relación con clientes (Asia)','Singapur (cobertura clústeres Asia South y JANA)',null,'mark.attard@citi.com','patron_no_verificado','influencer',4,'Cara comercial de Citi Token Services y custodia cripto ante clientes en Asia (entrevista Taipei Times, 6 jul 2026: CTS vivo en 5 mercados, USD y EUR); alternativa si el foco es cross-listing o liquidez en Singapur/Hong Kong y referencia del rol regional de ''client relationships'' que Kabal debe buscar para LatAm.','https://www.taipeitimes.com/News/biz/archives/2026/07/06/2003860324','Verificación: cargo confirmado por Taipei Times (6 jul 2026): ''Head of Digital Assets and Client Relationships for Citi Global Financial Services, responsible for the Asia South and JANA clusters''. La fuente CNA original (https://www.cna.com.tw/business/english/438343) no aparece en búsqueda como artículo que lo mencione y no pudo abrirse desde este entorno, por lo que se reemplazó por Taipei Times. Ubicación Singapur según bio ABS 2024 (entonces ''Head of Digital Assets and Client Engagement, TTS, based in Singapore''; antes en Onyx by J.P. Morgan). Cobertura Asia, no LatAm. Correo derivado del patrón nombre.apellido@citi.com (no verificado).'),
('Rekha Jogia-Soni','Media Relations, Citi Services (contacto de prensa en comunicados de digital assets)','Citi Communications – Services / Digital Assets','Londres, Reino Unido',null,'rekha.jogiasoni@citi.com','patron_no_verificado','canal_generico',5,'Contacto de medios citado en el comunicado Citi/METACO (2022) sobre custodia de activos digitales; sirve como canal de respaldo para que enrute la propuesta al equipo de digital assets si no hay respuesta directa.','https://www.businesswire.com/news/home/20220621005892/en','Verificación: el comunicado de BusinessWire no pudo reabrirse desde este entorno (bloqueo de red 403 del proxy; WebFetch también falló), por lo que la publicación visible del correo NO se confirmó en esta pasada; se degrada de ''publico'' a ''patron_no_verificado'' hasta que alguien abra el enlace y confirme la dirección. Evidencia de 2022 (anterior a 2025); puede haber cambiado de rol o dejado Citi. No es decisora: usar solo como fallback de enrutamiento.')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
